def tuple_intersection(list1, list2):
    def normalize(t):
        return tuple(sorted(t))

    set1 = {normalize(t) for t in list1}
    set2 = {normalize(t) for t in list2}

    common = set1 & set2

    result = set()
    for t in list1:
        if normalize(t) in common:
            result.add(t)
    for t in list2:
        if normalize(t) in common:
            result.add(t)

    return result
